                    randomSeed = prop.Value.GetInt32();
                    continue;
                }
                if (prop.NameEquals("stepLRGamma"u8))
                {
                    stepLRGammaIsDefined = true;
                    if (prop.Value.ValueKind == JsonValueKind.Null)
                    {
                        stepLRGamma = null;
