                    continue;
                }
                if (prop.NameEquals("validationBatchSize"u8))
                {
                    validationBatchSizeIsDefined = true;
                    if (prop.Value.ValueKind == JsonValueKind.Null)
                    {
                        validationBatchSize = null;
                        continue;
